scan_table_check.script:
(function(engine, current) {
    var messages = new global.EcsUpdateSet(current).sharedArtifacts();
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-CFG-005',
        title: 'Artifact also changed in another in-progress update set',
        recommendation: 'Coordinate with the owner of the other update set: merge the work into one update set, or complete and promote them in a deliberate order. Otherwise whichever is committed last silently overwrites the other.',
        current: current
    });
    for (var i = 0; i < messages.length; i++) {
        report.addRecord(messages[i]);
    }
    engine.finding.setCurrentSource(current);
    report.flush();
})(engine, current);
